#!/usr/bin/env node
// Fails if committed files could leak secrets. Never prints a value: findings show
// the file, line, key and a fingerprint (first 12 hex chars of sha256).
//
//   1. Local env files are tracked: .dev.vars*, .env* (only *.example is allowed).
//   2. A generated worker-configuration.d.ts / cloudflare-env.d.ts:
//      - types a secret-named Env member as a non-empty string literal, or
//      - has a literal that looks like a credential, or
//      - was generated by `wrangler types` without `--env-file <*.example>`
//        (plain `wrangler types` reads your real .dev.vars).
//   3. Any tracked text file contains a high-confidence credential pattern
//      (Resend/Stripe/GitHub/Slack/AWS keys, PEM private keys).
//
// A line can opt out of check 3 with the marker `secret-scan:allow` (fake fixtures only).
// Usage: node scripts/check-committed-secrets.mjs [--self-test]
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import console from 'node:console';

const fp = (v) => createHash('sha256').update(v).digest('hex').slice(0, 12);

const ENV_FILE = /^\.(dev\.vars|env)(\..+)?$/;
const GENERATED_TYPES = /(^|\/)(worker-configuration|cloudflare-env)\.d\.ts$/;
const SECRET_NAME = /SECRET|TOKEN|PASSWORD|PASSWD|PRIVATE|CREDENTIAL|SALT|API_?KEY|(^|_)KEY($|_)|MASTER/i;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Credential formats that are near-certain wherever they appear.
const TOKEN_PATTERNS = [
	['resend-api-key', /\bre_[A-Za-z0-9]{8,}_[A-Za-z0-9]{16,}\b/],
	['stripe-key', /\b(sk|rk)_(live|test)_[A-Za-z0-9]{16,}\b/],
	['github-token', /\b(gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{40,})\b/],
	['slack-token', /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/],
	['aws-access-key', /\b(AKIA|ASIA)[A-Z0-9]{16}\b/],
	['private-key', /-----BEGIN ([A-Z]+ )?PRIVATE KEY-----/],
];

/** True when a literal from a generated Env type looks like a credential. */
export function looksLikeSecret(v) {
	if (v.length < 16 || /\s/.test(v) || v.includes('://') || UUID.test(v)) return false;
	if (TOKEN_PATTERNS.some(([, re]) => re.test(v))) return true;
	if (/^(re|sk|rk|pk|whsec|ghp|gho|ghs)_[A-Za-z0-9_]{12,}$/.test(v)) return true;
	if (/^eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+/.test(v)) return true; // JWT
	if (/^[0-9a-f]{32,}$/i.test(v)) return true; // hex key
	// base64 / base64url blob with mixed character classes
	return /^[A-Za-z0-9+/_-]{32,}={0,2}$/.test(v) && /[A-Z]/.test(v) && /[a-z]/.test(v) && /[0-9]/.test(v);
}

/** Returns [{line, key, literal}] for string-literal-typed members of Env-like interfaces. */
export function envLiterals(text) {
	const out = [];
	const head = /interface\s+(\w*Env)\b[^{]*\{/g; // Env, CloudflareEnv, StageEnv, __BaseEnv_Env, ...
	while (head.exec(text)) {
		let depth = 1;
		let i = head.lastIndex;
		const start = i;
		while (i < text.length && depth > 0) {
			if (text[i] === '{') depth++;
			else if (text[i] === '}') depth--;
			i++;
		}
		const body = text.slice(start, i - 1);
		const baseLine = text.slice(0, start).split('\n').length;
		body.split('\n').forEach((raw, idx) => {
			const member = raw.match(/^\s*["']?([A-Za-z_$][\w$-]*)["']?\??\s*:\s*(.+?);?\s*$/);
			if (!member) return;
			for (const lit of member[2].matchAll(/"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)'/g)) {
				out.push({ line: baseLine + idx, key: member[1], literal: lit[1] ?? lit[2] });
			}
		});
	}
	return out;
}

/** Checks the `wrangler types` command recorded in the generated header. */
export function headerProblem(text) {
	const cmd = text.match(/Generated by Wrangler by running `(wrangler types[^`]*)`/);
	if (!cmd) return null;
	const files = [...cmd[1].matchAll(/--env-file(?:=|\s+)(\S+)/g)].map((x) => x[1]);
	if (files.length === 0) return `generated by \`${cmd[1]}\` without --env-file, so it may contain values from .dev.vars`;
	const bad = files.filter((f) => !f.endsWith('.example'));
	return bad.length ? `--env-file must point at a *.example file (got ${bad.join(', ')})` : null;
}

export function scanFile(file, text) {
	const findings = [];
	if (GENERATED_TYPES.test(file)) {
		const h = headerProblem(text);
		if (h) findings.push({ file, line: 2, rule: 'unsafe-typegen', detail: h });
		for (const { line, key, literal } of envLiterals(text)) {
			if (!literal) continue;
			if (SECRET_NAME.test(key)) findings.push({ file, line, rule: 'secret-literal-type', detail: `${key} fp=${fp(literal)}` });
			else if (looksLikeSecret(literal)) findings.push({ file, line, rule: 'credential-literal-type', detail: `${key} fp=${fp(literal)}` });
		}
	}
	text.split('\n').forEach((l, idx) => {
		if (l.includes('secret-scan:allow')) return;
		for (const [rule, re] of TOKEN_PATTERNS) {
			const hit = l.match(re);
			if (hit) findings.push({ file, line: idx + 1, rule, detail: `fp=${fp(hit[0])}` });
		}
	});
	return findings;
}

function main() {
	const files = execFileSync('git', ['ls-files', '-z'], { encoding: 'utf8', maxBuffer: 1 << 28 }).split('\0').filter(Boolean);
	const findings = [];
	for (const file of files) {
		const base = path.basename(file);
		if (ENV_FILE.test(base) && !base.endsWith('.example')) {
			findings.push({ file, line: 0, rule: 'env-file-committed', detail: 'local env files must not be committed; commit a *.example with placeholders instead' });
			continue;
		}
		let buf;
		try {
			buf = readFileSync(file);
		} catch {
			continue; // deleted in the working tree, or a submodule
		}
		if (buf.length > 5_000_000 || buf.subarray(0, 8000).includes(0)) continue; // binary or huge
		findings.push(...scanFile(file, buf.toString('utf8')));
	}
	if (findings.length === 0) {
		console.log(`committed-secrets: OK (${files.length} tracked files scanned)`);
		return;
	}
	for (const f of findings) {
		console.log(`::error file=${f.file}${f.line ? `,line=${f.line}` : ''}::${f.rule}: ${f.detail}`);
	}
	console.log(`\ncommitted-secrets: ${findings.length} finding(s). Values are never printed; fp = first 12 hex of sha256.`);
	console.log('Fix: regenerate types with the package `types`/`cf-typegen` script (it reads only .dev.vars.example),');
	console.log('untrack local env files (git rm --cached), and rotate any real credential that was committed.');
	process.exitCode = 1;
}

function selfTest() {
	const assert = (c, m) => {
		if (!c) throw new Error(`self-test failed: ${m}`);
	};
	const fake = 're_' + 'Ab12Cd34' + '_' + 'Q'.repeat(8) + 'w1e2r3t4'; // assembled so this file never matches itself
	const dts = [
		'// Generated by Wrangler by running `wrangler types` (hash: x)',
		'declare namespace Cloudflare {',
		'\tinterface StageEnv {',
		'\t\tSTAGE_TOKEN: "abc";',
		'\t}',
		'\tinterface Env {',
		'\t\tENVIRONMENT: "production" | "qa";',
		`\t\tRESEND_API_KEY: "${fake}";`,
		'\t\tSESSION_SECRET: "short";',
		'\t\tAUDIT_WEBHOOK_SECRET: "";',
		'\t\tCLIENT_ID: "109a1087-6626-40f7-8a7f-7f42f83f4f30";',
		`\t\tBLOB: "${'a1B2'.repeat(10)}";`,
		'\t\tSAFE: string;',
		'\t}',
		'}',
	].join('\n');
	const rules = scanFile('apps/x/worker-configuration.d.ts', dts).map((f) => `${f.rule}:${f.detail.split(' ')[0]}`);
	assert(rules.includes('unsafe-typegen:generated'), 'flags plain wrangler types');
	assert(rules.includes('secret-literal-type:RESEND_API_KEY'), 'flags secret-named literal');
	assert(rules.includes('secret-literal-type:SESSION_SECRET'), 'flags short secret-named literal');
	assert(rules.includes('secret-literal-type:STAGE_TOKEN'), 'scans per-env interfaces');
	assert(rules.includes('credential-literal-type:BLOB'), 'flags base64-looking literal');
	assert(rules.some((r) => r.startsWith('resend-api-key:fp=')), 'flags resend key pattern');
	assert(!rules.some((r) => /ENVIRONMENT|CLIENT_ID|AUDIT_WEBHOOK_SECRET|SAFE/.test(r)), 'no false positives');
	const safe = '// Generated by Wrangler by running `wrangler types --env-file .dev.vars.example --strict-vars=false` (hash: x)\ninterface Env { A: string; }';
	assert(scanFile('worker-configuration.d.ts', safe).length === 0, 'safe header passes');
	assert(headerProblem('Generated by Wrangler by running `wrangler types --env-file=.dev.vars`') !== null, 'rejects non-example env file');
	assert(ENV_FILE.test('.dev.vars.qa') && ENV_FILE.test('.env.test') && !ENV_FILE.test('env.ts'), 'env file pattern');
	assert(scanFile('a.md', `key ${fake} secret-scan:allow`).length === 0, 'allow marker');
	console.log('committed-secrets self-test: OK');
}

if (process.argv.includes('--self-test')) selfTest();
else main();
